update public.spell_catalog set
name_ru='Сигнал тревоги', casting_time='1 минута', spell_range='30 футов', area='Дверь, окно или куб до 20 футов', duration='8 часов', components=array['В','С','М'], material='колокольчик и серебряная проволока', check_type='', damage='', effect_summary='Ставит магическую сигнализацию на дверь, окно или небольшую область. Можно заранее исключить существ и выбрать слышимый или мысленный сигнал.', upcast='', notes='Ритуал. Слышимый сигнал звучит 10 секунд в пределах 60 футов; мысленный предупреждает в пределах 1 мили и будит спящего заклинателя.', author_description='Ты назначаешь участок мира, куда без спроса лучше не лезть. Если кто-то всё-таки полезет, магия сообщит об этом — громко или прямо тебе в голову. Для следопыта это называется предусмотрительностью. Для волшебника — редким случаем, когда он сначала думает, а потом колдует.', author_comment='Полезнейший способ узнать, что тебя снова пришли убивать, чуть раньше, чем они откроют дверь.' where slug='alarm';

update public.spell_catalog set
name_ru='Дружба с животными', casting_time='Действие', spell_range='30 футов', area='1 зверь, которого видно', duration='24 часа', components=array['В','С','М'], material='кусочек еды', check_type='Спасбросок Мудрости', damage='', effect_summary='При провале зверь получает состояние Очарованный на 24 часа. Эффект заканчивается, если ты или союзник наносите ему урон.', upcast='+1 зверь за каждый уровень ячейки выше 1.', notes='Работает только на тип Зверь. Цель должна быть видна.', author_description='Ты убеждаешь зверя, что ты не представляешь угрозы. Как правило, кусок еды в материальных компонентах объясняет успех куда честнее всей магической теории.', author_comment='Удивительно: животные доверяют друидам чаще людей. Возможно, потому что ещё не слышали их разговоров о балансе природы.' where slug='animal-friendship';

update public.spell_catalog set
name_ru='Порча', casting_time='Действие', spell_range='30 футов', area='До трёх видимых существ', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='капля крови', check_type='Спасбросок Харизмы', damage='', effect_summary='При провале цель вычитает 1к4 из бросков атаки и спасбросков до конца заклинания.', upcast='+1 цель за каждый уровень ячейки выше 1.', notes='Каждая цель делает собственный спасбросок Харизмы.', author_description='Ты немного ухудшаешь жизнь сразу нескольким существам: рука дрогнула, защита подвела, удар ушёл мимо. Никакой красоты, зато стабильно работает. Жрецы любят рассказывать, что это кара свыше. Конечно. Не они же бросок провалили.', author_comment='Если бог действительно лично следит за каждым минусом к1к4, у него подозрительно много свободного времени.' where slug='bane';

update public.spell_catalog set
name_ru='Благословение', casting_time='Действие', spell_range='30 футов', area='До трёх существ', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='священный символ стоимостью 5+ зм', check_type='', damage='', effect_summary='Цели добавляют 1к4 к броскам атаки и спасброскам.', upcast='+1 цель за каждый уровень ячейки выше 1.', notes='Не требует спасброска; цели выбираются заклинателем.', author_description='Жрец машет символом, произносит что-нибудь уверенным голосом — и вы действительно начинаете бить точнее и выживать чаще. Ненавижу случаи, когда реклама соответствует товару.', author_comment='Пользуйся, пока у жреца есть ячейки. Потом благословение обычно превращается в пожелание удачи с безопасного расстояния.' where slug='bless';

update public.spell_catalog set
name_ru='Пылающие ладони', casting_time='Действие', spell_range='На себя', area='Конус 15 футов', duration='Мгновенно', components=array['В','С'], material=null, check_type='Спасбросок Ловкости', damage='3к6 огнём; половина при успехе', effect_summary='Пламя поражает всех существ в конусе. Незакреплённые воспламеняемые предметы в области загораются.', upcast='+1к6 урона за каждый уровень ячейки выше 1.', notes='Предметы не загораются, если их носят или держат.', author_description='Ты вытягиваешь руки и превращаешь пространство перед собой в короткое доказательство того, что пожарная безопасность существует не зря. Волшебники называют это базовым боевым заклинанием. Владельцы таверн — причиной залога.', author_comment='Пятнадцать футов огня. Достаточно далеко, чтобы обжечь друзей, и достаточно близко, чтобы потом услышать их мнение.' where slug='burning-hands';

update public.spell_catalog set
name_ru='Очарование личности', casting_time='Действие', spell_range='30 футов', area='1 видимый гуманоид', duration='1 час', components=array['В','С'], material=null, check_type='Спасбросок Мудрости', damage='', effect_summary='При провале гуманоид становится Очарованным и Дружелюбным к тебе. Эффект заканчивается, если ты или союзники причиняете ему вред. После окончания цель понимает, что была очарована.', upcast='+1 цель за каждый уровень ячейки выше 1.', notes='Если ты или союзники сражаетесь с целью, она делает спасбросок с Преимуществом. Только гуманоиды.', author_description='Магически убеждаешь человека, что ты ему нравишься. На час. После чего он узнаёт, что его волю аккуратно обошли стороной. Отличный способ превратить временного друга в будущую проблему.', author_comment='Если для хорошего первого впечатления тебе нужен спасбросок Мудрости, проблема, возможно, не в Харизме.' where slug='charm-person';

update public.spell_catalog set
name_ru='Хроматическая сфера', casting_time='Действие', spell_range='90 футов', area='1 существо или объект', duration='Мгновенно', components=array['В','С','М'], material='алмаз стоимостью 50+ зм', check_type='Дальняя атака заклинанием', damage='3к8 выбранным типом: кислота, холод, огонь, молния, яд или звук', effect_summary='При попадании наносит 3к8 выбранного энергетического урона. Если на двух или более к8 выпало одинаковое число, сфера перескакивает на новую цель в пределах 30 футов и требует нового броска атаки.', upcast='+1к8 урона за уровень ячейки выше 1. Максимум перескоков равен уровню потраченной ячейки; одна цель не может быть поражена дважды одним применением.', notes='На ячейке 1 уровня сфера после первого перескока больше не прыгает.', author_description='Один шар, шесть способов испортить кому-то день и небольшая азартная игра на одинаковых к8. Волшебники любят называть это универсальностью. Я называю это человеком, который принёс алмаз, чтобы бросаться разноцветной смертью.', author_comment='Если шар начал прыгать между целями, поздравляю: математика наконец решила кого-то убить.' where slug='chromatic-orb';

update public.spell_catalog set
name_ru='Цветной всплеск', casting_time='Действие', spell_range='На себя', area='Конус 15 футов', duration='Мгновенно', components=array['В','С','М'], material='щепотка цветного песка', check_type='Спасбросок Телосложения', damage='', effect_summary='Существа в конусе при провале получают состояние Ослеплённый до конца твоего следующего хода.', upcast='', notes='Каждое существо в области делает отдельный спасбросок.', author_description='Ты швыряешь в противников вспышку света настолько яркую и нелепую, что они временно перестают видеть. Иногда тактическое преимущество выглядит как нападение на праздник красок.', author_comment='Лучший бой — тот, где противник ничего не видит. Второй лучший — тот, где бард тоже ничего не видит.' where slug='color-spray';

update public.spell_catalog set
name_ru='Приказ', casting_time='Действие', spell_range='60 футов', area='1 видимое существо', duration='Мгновенно', components=array['В'], material=null, check_type='Спасбросок Мудрости', damage='', effect_summary='При провале цель на следующем ходу выполняет один из приказов: Подойди, Брось, Беги, Падай или Стой.', upcast='+1 цель за каждый уровень ячейки выше 1.', notes='Подойди — движется к тебе и заканчивает ход в 5 футах. Брось — роняет удерживаемое и заканчивает ход. Беги — максимально удаляется. Падай — получает Лежащий и заканчивает ход. Стой — не движется и не совершает действие или бонусное действие.', author_description='Одно слово, один спасбросок и краткий момент, когда кто-то другой обязан считать твою идею хорошей. Жрецы особенно любят это заклинание. Наконец-то проповедь, которую можно навязать механически.', author_comment='Если человек слушается тебя только после магического вмешательства, руководитель из тебя всё ещё сомнительный.' where slug='command';

update public.spell_catalog set
name_ru='Понимание языков', casting_time='Действие', spell_range='На себя', area='Ты', duration='1 час', components=array['В','С','М'], material='щепотка сажи и соли', check_type='', damage='', effect_summary='Ты понимаешь буквальный смысл любой услышанной речи, жестового языка и письменного текста. Для чтения надо касаться поверхности; одна страница занимает около минуты.', upcast='', notes='Ритуал. Не расшифровывает тайные символы, шифры и скрытые сообщения.', author_description='На час ты понимаешь, что тебе говорят, независимо от языка. К сожалению, заклинание переводит слова, а не здравый смысл. Поэтому речь барда останется такой же бессодержательной, просто теперь точно.', author_comment='Знать все языки полезно. Особенно когда хочешь услышать, как тебя оскорбляют международно.' where slug='comprehend-languages';

update public.spell_catalog set
name_ru='Создание или уничтожение воды', casting_time='Действие', spell_range='30 футов', area='Открытая ёмкость или куб 30 футов', duration='Мгновенно', components=array['В','С','М'], material='смесь воды и песка', check_type='', damage='', effect_summary='Создаёт до 10 галлонов чистой воды в открытой ёмкости либо дождь в кубе 30 футов, гасящий открытое пламя. Либо уничтожает до 10 галлонов воды или туман в кубе 30 футов.', upcast='+10 галлонов воды или +5 футов к стороне куба за каждый уровень ячейки выше 1.', notes='Созданный дождь гасит открытое пламя в области.', author_description='Можно создать воду. Можно уничтожить воду. Друиды назовут это властью над стихией. Любой человек, три дня идущий по пустыне, назовёт первое применение единственным, которое его сейчас интересует.', author_comment='Редкий случай, когда маг способен решить бытовую проблему, не создавая две новые.' where slug='create-or-destroy-water';

update public.spell_catalog set
name_ru='Лечение ран', casting_time='Действие', spell_range='Касание', area='1 существо', duration='Мгновенно', components=array['В','С'], material=null, check_type='', damage='Лечение: 2к8 + модификатор заклинательной характеристики', effect_summary='Существо, которого ты касаешься, восстанавливает хиты.', upcast='+2к8 лечения за каждый уровень ячейки выше 1.', notes='Требует касания цели.', author_description='Прикладываешь руку — рана становится заметно менее смертельной. Всё просто. Ни молитвенного маркетинга, ни пространных объяснений о воле богов в самой механике нет. Это уже жрецы добавляют бесплатно.', author_comment='Воин с аптечкой всё ещё дешевле. Но, признаю, два к8 выглядят убедительно.' where slug='cure-wounds';

update public.spell_catalog set
name_ru='Обнаружение зла и добра', casting_time='Действие', spell_range='На себя', area='Радиус 30 футов вокруг тебя', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Чувствуешь местоположение аберраций, небожителей, элементалей, фей, исчадий и нежити в пределах 30 футов, а также действие Освящения.', upcast='', notes='Блокируется 1 футом камня, земли или дерева; 1 дюймом металла; тонким листом свинца.', author_description='Заклинание сообщает, что рядом находится что-то из списка существ, с которыми обычно заканчивают переговоры раньше времени. Полезно. Название, правда, врёт: человеческих мерзавцев оно не обнаруживает.', author_comment='Если ничего не засветилось, не расслабляйся. Самые опасные чудовища иногда числятся гуманоидами.' where slug='detect-evil-and-good';

update public.spell_catalog set
name_ru='Обнаружение магии', casting_time='Действие', spell_range='На себя', area='Радиус 30 футов вокруг тебя', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Чувствуешь магические эффекты в радиусе 30 футов. Действием Магии можешь увидеть слабую ауру на видимом существе или объекте и узнать школу заклинания, создавшего эффект.', upcast='', notes='Ритуал. Блокируется 1 футом камня, земли или дерева; 1 дюймом металла; тонким листом свинца.', author_description='Позволяет понять, что вокруг магическое. Незаменимо в руинах, лабораториях и любой комнате, где волшебник уже сказал: «Не трогай это».', author_comment='Если вся комната светится магией, лучший результат проверки — ближайший выход.' where slug='detect-magic';

update public.spell_catalog set
name_ru='Обнаружение яда и болезней', casting_time='Действие', spell_range='На себя', area='Радиус 30 футов вокруг тебя', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='лист тиса', check_type='', damage='', effect_summary='Чувствуешь местоположение ядов, ядовитых существ и магических зараз в пределах 30 футов и определяешь их вид.', upcast='', notes='Ритуал. Блокируется 1 футом камня, земли или дерева; 1 дюймом металла; тонким листом свинца.', author_description='Магически выясняешь, что суп отравлен, паук ядовит, а кашель пленника — не просто простуда. Следопыт обычно делает примерно то же самое, только посмотрев на суп, паука и пленника.', author_comment='Очень полезно, если плут внезапно предложил тебе напиток и улыбается.' where slug='detect-poison-and-disease';

update public.spell_catalog set
name_ru='Маскировка', casting_time='Действие', spell_range='На себя', area='Ты и надетое/несомое снаряжение', duration='1 час', components=array['В','С'], material=null, check_type='Интеллект (Расследование) против Сл спасброска заклинаний при изучении', damage='', effect_summary='Иллюзорно меняет твою внешность, одежду, броню, оружие и вещи. Можно казаться на 1 фут выше/ниже, тяжелее/легче, но строение конечностей должно оставаться тем же.', upcast='', notes='Физический контакт раскрывает несоответствие. Существо может действием Изучения проверить иллюзию.', author_description='Ты выглядишь как кто-то другой, пока никто не решит проверить руками. Отличный инструмент для разведки. Или для плута, которому почему-то снова нельзя показывать настоящее лицо.', author_comment='Если маскировка нужна тебе каждый день, возможно, стоит перестать давать людям причины тебя запоминать.' where slug='disguise-self';

update public.spell_catalog set
name_ru='Диссонирующий шёпот', casting_time='Действие', spell_range='60 футов', area='1 видимое существо', duration='Мгновенно', components=array['В'], material=null, check_type='Спасбросок Мудрости', damage='3к6 психическим; половина при успехе', effect_summary='При провале цель получает психический урон и, если может, немедленно тратит Реакцию, чтобы максимально далеко отойти от тебя безопасным маршрутом.', upcast='+1к6 урона за каждый уровень ячейки выше 1.', notes='При успехе цель получает только половину урона и не обязана отходить.', author_description='Вкладываешь в чужую голову настолько отвратительный звук, что человек предпочитает немедленно уйти. Барды называют это магией. Остальные иногда достигают похожего эффекта обычным выступлением.', author_comment='Редкое заклинание барда, где побег слушателя считается успехом.' where slug='dissonant-whispers';

update public.spell_catalog set
name_ru='Божественная благосклонность', casting_time='Бонусное действие', spell_range='На себя', area='Твои атаки оружием', duration='1 минута', components=array['В','С'], material=null, check_type='', damage='+1к4 излучением к каждому попаданию оружием', effect_summary='До конца заклинания каждое попадание твоей атакой оружием наносит дополнительно 1к4 урона излучением.', upcast='', notes='Не требует концентрации.', author_description='Паладин получает небольшую добавку святого света к каждому удару. По сути, молитва, которая хотя бы понимает, что меч уже делает основную работу.', author_comment='Вот почему паладинов я терплю: бог богом, а бить всё равно приходится самому.' where slug='divine-favor';

update public.spell_catalog set
name_ru='Божественная кара', casting_time='Бонусное действие сразу после попадания оружием ближнего боя или безоружным ударом', spell_range='На себя', area='Цель только что попавшей атаки', duration='Мгновенно', components=array['В'], material=null, check_type='', damage='+2к8 излучением; ещё +1к8 по исчадию или нежити', effect_summary='Сразу после попадания усиливает уже нанесённую атаку дополнительным уроном излучением.', upcast='+1к8 урона за каждый уровень ячейки выше 1.', notes='Триггер: только сразу после успешного попадания оружием ближнего боя или безоружным ударом.', author_description='Ты сначала попадаешь, а уже потом решаешь, заслуживает ли цель ещё и божественного осуждения. Наконец-то религиозная процедура с разумным порядком действий.', author_comment='Паладинский вариант аргумента: сначала меч, потом теология. Уважаю последовательность.' where slug='divine-smite';

update public.spell_catalog set
